1	import { WikiRotation } from '../../utils/WikiEnricher.js';
2	import { createLogger } from '../../utils/logger.js';
3	import { readFileSync, existsSync } from 'fs';
4	import * as fs from 'fs';
5	import { join } from 'path';
6	
7	const logger = createLogger('PVMERotationLimb');
8	
9	export interface PVMEBossData {
10	    boss: string;
11	    lastUpdated: string;
12	    bestiary: Record<string, string>;
13	    rotations: WikiRotation[];
14	}
15	
16	/**
17	 * PVMERotationLimb
18	 * 
19	 * Manages the execution of high-fidelity combat sequences ingested from PVME.
20	 * Handles phase-specific transitions and rotation selection.
21	 */
22	export class PVMERotationLimb {
23	    private static instance: PVMERotationLimb;
24	    private bossData: Map<string, PVMEBossData> = new Map();
25	    private activeSequences: Map<string, { boss: string; rotationIdx: number; abilityIdx: number }> = new Map();
26	    private globalPhases: Map<string, string> = new Map();
27	
28	    private constructor() {
29	        this.loadIngestedData();
30	    }
31	
32	    public static getInstance(): PVMERotationLimb {
33	        if (!this.instance) {
34	            this.instance = new PVMERotationLimb();
35	        }
36	        return this.instance;
37	    }
38	
39	    private loadIngestedData(): void {
40	        const dataDir = join(process.cwd(), 'data', 'pvme');
41	        if (!existsSync(dataDir)) return;
42	
43	        const files = fs.readdirSync(dataDir);
44	        for (const file of files) {
45	            if (!file.endsWith('.json')) continue;
46	            const p = join(dataDir, file);
47	            try {
48	                const data = JSON.parse(readFileSync(p, 'utf8')) as PVMEBossData;
49	                this.bossData.set(data.boss.toLowerCase(), data);
50	                logger.info({ boss: data.boss, file }, 'Loaded PVME rotation data');
51	            } catch (err) {
52	                logger.error({ file, err }, 'Failed to load PVME data');
53	            }
54	        }
55	    }
56	
57	    /**
58	     * Get the next ability from the PVME rotation for a given target.
59	     * Returns null if no PVME data exists for the target or rotation is complete.
60	     */
61	    public getNextAbility(entityId: string, bossName: string): { name: string, predicate?: string } | null {
62	        const data = this.bossData.get(bossName.toLowerCase());
63	        if (!data || data.rotations.length === 0) return null;
64	
65	        let active = this.activeSequences.get(entityId);
66	        if (!active || active.boss !== bossName) {
67	            // Start a new sequence (default to first Advanced rotation if possible)
68	            const rotIdx = data.rotations.findIndex(r => r.label.toLowerCase().includes('advanced')) || 0;
69	            active = { boss: bossName, rotationIdx: rotIdx >= 0 ? rotIdx : 0, abilityIdx: 0 };
70	            this.activeSequences.set(entityId, active);
71	            logger.info({ boss: bossName, entityId, rotation: data.rotations[active.rotationIdx].label }, 'Started PVME sequence');
72	        }
73	
74	        const rotation = data.rotations[active.rotationIdx];
75	        if (active.abilityIdx >= rotation.abilities.length) {
76	            // Rotation complete, restart or loop
77	            active.abilityIdx = 0;
78	        }
79	
80	        const abilityObj = rotation.abilities[active.abilityIdx];
81	        active.abilityIdx++;
82	        
83	        return abilityObj;
84	    }
85	
86	    /**
87	     * Get the next ability from the PVME rotation for a given target.
88	     * Returns null if no PVME data exists for the target or rotation is complete.
89	     */
90	    public peekNextAbility(entityId: string, bossName: string): { name: string, predicate?: string } | null {
91	        const data = this.bossData.get(bossName.toLowerCase());
92	        if (!data || data.rotations.length === 0) return null;
93	
94	        let active = this.activeSequences.get(entityId);
95	        if (!active || active.boss !== bossName) {
96	            // Lazy init using global phase if available
97	            const phase = this.globalPhases.get(bossName.toLowerCase()) || 'default';
98	            let rotIdx = data.rotations.findIndex(r => r.section.toLowerCase().includes(phase.toLowerCase()));
99	            if (rotIdx === -1) rotIdx = 0;
100	
101	            active = { boss: bossName, rotationIdx: rotIdx, abilityIdx: 0 };
102	            this.activeSequences.set(entityId, active);
103	        }
104	
105	        const rotation = data.rotations[active.rotationIdx];
106	        const idx = active.abilityIdx >= rotation.abilities.length ? 0 : active.abilityIdx;
107	        
108	        return rotation.abilities[idx];
109	    }
110	
111	    public getActiveRotationLabel(id: string): string | undefined {
112	        const active = this.activeSequences.get(id);
113	        if (active) {
114	            const data = this.bossData.get(active.boss.toLowerCase());
115	            return data?.rotations[active.rotationIdx]?.section || data?.rotations[active.rotationIdx]?.label;
116	        }
117	
118	        const global = this.globalPhases.get(id.toLowerCase());
119	        if (global) return global;
120	
121	        return undefined;
122	    }
123	
124	    /**
125	     * Reset the active sequence for an entity (e.g. on target swap or death).
126	     */
127	    public resetSequence(entityId: string): void {
128	        this.activeSequences.delete(entityId);
129	    }
130	
131	    /**
132	     * Set the specific phase/section of a rotation.
133	     * Can be called with a boss name (global) or entityId (specific instance).
134	     */
135	    public setPhase(id: string, sectionName: string): void {
136	        const key = id.toLowerCase();
137	        
138	        // Update global phase for future sequences
139	        if (this.bossData.has(key)) {
140	            this.globalPhases.set(key, sectionName);
141	        }
142	
143	        // Update active sequence if it exists
144	        const active = this.activeSequences.get(id);
145	        if (active) {
146	            const data = this.bossData.get(active.boss.toLowerCase());
147	            if (data) {
148	                const newRotIdx = data.rotations.findIndex(r => r.section.toLowerCase().includes(sectionName.toLowerCase()));
149	                if (newRotIdx >= 0) {
150	                    active.rotationIdx = newRotIdx;
151	                    active.abilityIdx = 0;
152	                    logger.info({ id, section: sectionName }, 'Switched active rotation phase');
153	                }
154	            }
155	        }
156	    }
157	}
