1	import { SovereignAvatar } from '../../core/models.js';
2	import { ServerOpcode } from '../../core/ProtocolOpcodes.js';
3	import { BitStream } from '../../utils/BitStream.js';
4	import { SovereignAvatarEntity } from '../../core/SovereignAvatar.js';
5	import { MovementBlockDecoder } from './world/MovementBlockDecoder.js';
6	import { AppearanceBlockDecoder } from './world/AppearanceBlockDecoder.js';
7	import { AnimationBlockDecoder } from './world/AnimationBlockDecoder.js';
8	import { HitsplatBlockDecoder } from './world/HitsplatBlockDecoder.js';
9	import { MapPacketDecoder } from './world/MapPacketDecoder.js';
10	import { VariableBlockDecoder } from './world/VariableBlockDecoder.js';
11	import { VarbitSovereigntyLimb } from '../spatial/VarbitSovereigntyLimb.js';
12	import { SpatialSovereigntyLimb } from '../spatial/SpatialSovereigntyLimb.js';
13	import { createLogger } from "../../utils/logger.js";
14	import { ByteStream } from "../../utils/ByteStream.js";
15	
16	const logger = createLogger('WorldStateLimb');
17	
18	/**
19	 * WorldStateLimb - Protocol 947 World Synchronizer
20	 * Coordinates the decoding of bitstream world-state and updates the local avatar.
21	 */
22	export class WorldStateLimb {
23	    private static instance: WorldStateLimb;
24	    private avatar: SovereignAvatar;
25	    private movementDecoder: MovementBlockDecoder;
26	    private appearanceDecoder: AppearanceBlockDecoder;
27	    private animationDecoder: AnimationBlockDecoder;
28	    private hitsplatDecoder: HitsplatBlockDecoder;
29	    private mapDecoder: MapPacketDecoder;
30	
31	    private constructor(avatar: SovereignAvatar) {
32	        this.avatar = avatar;
33	        this.movementDecoder = new MovementBlockDecoder();
34	        this.appearanceDecoder = new AppearanceBlockDecoder();
35	        this.animationDecoder = new AnimationBlockDecoder();
36	        this.hitsplatDecoder = new HitsplatBlockDecoder();
37	        this.mapDecoder = new MapPacketDecoder();
38	    }
39	
40	    public static getInstance(avatar?: SovereignAvatar): WorldStateLimb {
41	        if (!WorldStateLimb.instance) {
42	            if (!avatar) throw new Error("Avatar required for WorldStateLimb initialization.");
43	            WorldStateLimb.instance = new WorldStateLimb(avatar);
44	        }
45	        return WorldStateLimb.instance;
46	    }
47	
48	    /**
49	     * processPacket - Decodes and applies an incoming server packet.
50	     */
51	    public async processPacket(opcode: ServerOpcode, payload: Buffer): Promise<void> {
52	        switch (opcode) {
53	            case ServerOpcode.PLAYER_UPDATE:
54	                this.handlePlayerUpdate(payload);
55	                break;
56	            case ServerOpcode.REGION_LOAD_NORMAL:
57	                await this.handleRegionLoad(payload);
58	                break;
59	
60	            // Phase 11: Global State Bus (Variables)
61	            case ServerOpcode.VARP_SMALL: {
62	                const stream = new ByteStream(payload);
63	                const vps = VariableBlockDecoder.decodeVarpSmall(stream);
64	                VarbitSovereigntyLimb.getInstance().setVarp(vps.id, vps.value, this.avatar.state);
65	                break;
66	            }
67	            case ServerOpcode.VARP_LARGE: {
68	                const stream = new ByteStream(payload);
69	                const vpl = VariableBlockDecoder.decodeVarpLarge(stream);
70	                VarbitSovereigntyLimb.getInstance().setVarp(vpl.id, vpl.value, this.avatar.state);
71	                break;
72	            }
73	            case ServerOpcode.VARC: {
74	                const stream = new ByteStream(payload);
75	                const vc = VariableBlockDecoder.decodeVarc(stream);
76	                this.avatar.state.varcs.set(vc.id, vc.value);
77	                logger.info({ id: vc.id, value: vc.value }, 'VARC Synchronized');
78	                break;
79	            }
80	            case ServerOpcode.VARC_STRING: {
81	                const stream = new ByteStream(payload);
82	                const vcs = VariableBlockDecoder.decodeVarcString(stream);
83	                this.avatar.state.varcs.set(vcs.id, vcs.value);
84	                logger.info({ id: vcs.id, value: vcs.value }, 'VARC_STRING Synchronized');
85	                break;
86	            }
87	
88	            default:
89	                logger.warn({ opcode }, "Unhandled Server Opcode received.");
90	        }
91	    }
92	
93	    private handlePlayerUpdate(payload: Buffer): void {
94	        const stream = new BitStream(payload);
95	        
96	        // 1. Decode Local Player Movement
97	        const nextCoord = this.movementDecoder.decodeLocalPlayer(stream, this.avatar.coord);
98	        
99	        if (nextCoord.x !== this.avatar.x || nextCoord.y !== this.avatar.y) {
100	            this.avatar.coord = nextCoord;
101	            this.avatar.x = nextCoord.x;
102	            this.avatar.y = nextCoord.y;
103	            logger.info({ x: nextCoord.x, y: nextCoord.y }, "Avatar Movement Synced.");
104	        }
105	
106	        // 2. Process Sync Block (Appearance/Animations/Hitsplats)
107	        const hasUpdateBlock = stream.readBits(1);
108	        if (hasUpdateBlock) {
109	            let byteOffset = stream.getBytePosition();
110	            
111	            // Read Update Mask (assuming 1-byte for simulation/Rev 947 core)
112	            const mask = payload.readUInt8(byteOffset++);
113	            
114	            // 0x1: Appearance
115	            if (mask & 0x1) {
116	                this.appearanceDecoder.applyAppearance(payload.slice(byteOffset), this.avatar);
117	                // Assume fixed or calculated size for appearance for now. 
118	                // In a real client, each decoder returns bytesConsumed.
119	                byteOffset += 6; // Gender(1) + Colors(5)
120	                logger.debug("Appearance Block Applied.");
121	            }
122	
123	            // 0x2: Animation
124	            if (mask & 0x2) {
125	                const consumed = this.animationDecoder.applyAnimation(payload.slice(byteOffset), this.avatar);
126	                byteOffset += consumed;
127	                logger.info({ animId: this.avatar.metadata.lastAnimId }, "Animation Block Applied.");
128	            }
129	
130	            // 0x40: Hitsplats
131	            if (mask & 0x40) {
132	                this.hitsplatDecoder.applyHitsplats(payload.slice(byteOffset), this.avatar);
133	                logger.info("Hitsplat Block Applied.");
134	            }
135	        }
136	    }
137	
138	    private async handleRegionLoad(payload: Buffer): Promise<void> {
139	        const rebuild = this.mapDecoder.decodeRebuildNormal(payload);
140	        
141	        // 1. Sync Avatar
142	        this.avatar.coord = { x: rebuild.rx * 64, y: rebuild.ry * 64, plane: rebuild.plane };
143	        this.avatar.x = this.avatar.coord.x;
144	        this.avatar.y = this.avatar.coord.y;
145	        this.avatar.plane = rebuild.plane;
146	
147	        // 2. Sync Spatial Authority
148	        const spatial = SpatialSovereigntyLimb.getInstance();
149	        if ((spatial as any).setRegionAuthority) {
150	            await (spatial as any).setRegionAuthority(rebuild.rx, rebuild.ry);
151	        } else {
152	            // Fallback to existing loadMapsquare if new method isn't implemented yet
153	            await spatial.loadMapsquare(rebuild.rx, rebuild.ry);
154	        }
155	        
156	        logger.info({ rx: rebuild.rx, ry: rebuild.ry }, "World Region Grounded (Scene GPP).");
157	    }
158	}
