1	export enum InteractionCategory {
2	    DIALOGUE = 'DIALOGUE',         // talk, talk-to, talk at
3	    MECHANICAL = 'MECHANICAL',     // open, close, push, pull
4	    TRANSVERSAL = 'TRANSVERSAL',   // enter, climb, squeeze-through
5	    FORENSIC = 'FORENSIC',         // search, look, examine
6	    ECONOMY = 'ECONOMY',           // trade, shop, buy
7	    UNKNOWN = 'UNKNOWN'
8	}
9	
10	/**
11	 * Sovereign Vocabulary Limb
12	 * Translates raw jagex interaction strings into standardized AI mechanical states.
13	 */
14	export class SovereignVocabularyLimb {
15	    
16	    constructor() {
17	        console.log("SovereignVocabularyLimb: Semantic translation initialized.");
18	    }
19	
20	    /**
21	     * Normalizes a raw string (e.g., 'Talk-to', 'talk', 'Talk at') into a core handle.
22	     */
23	    public normalizeHandle(rawAction: string | null | undefined): string {
24	        if (!rawAction) return '';
25	        
26	        // Lowercase, trim, replace hyphens with spaces
27	        const normalized = rawAction.toLowerCase().trim().replace(/-/g, ' ');
28	
29	        return normalized;
30	    }
31	
32	    /**
33	     * Categorizes a normalized handle into an actionable AI state.
34	     */
35	    public categorize(action: string | null | undefined): InteractionCategory {
36	        const handle = this.normalizeHandle(action);
37	        if (!handle) return InteractionCategory.UNKNOWN;
38	
39	        if (handle.startsWith('talk')) return InteractionCategory.DIALOGUE;
40	        if (handle.startsWith('trade') || handle.includes('shop') || handle.includes('store')) return InteractionCategory.ECONOMY;
41	        if (handle.startsWith('open') || handle.startsWith('close') || handle === 'push' || handle === 'pull') return InteractionCategory.MECHANICAL;
42	        if (handle.startsWith('enter') || handle.startsWith('climb') || handle.includes('squeeze') || handle.includes('jump')) return InteractionCategory.TRANSVERSAL;
43	        if (handle.startsWith('search') || handle.startsWith('look') || handle.startsWith('examine') || handle.startsWith('read')) return InteractionCategory.FORENSIC;
44	
45	        return InteractionCategory.UNKNOWN;
46	    }
47	    
48	    /**
49	     * Determines if the action dictates shifting the physical state of the entity (e.g., opening a door).
50	     */
51	    public isStateShiftingAction(action: string | null | undefined): boolean {
52	        return this.categorize(action) === InteractionCategory.MECHANICAL;
53	    }
54	
55	    /**
56	     * Determines if the action dictates moving the probe's coordinate or plane.
57	     */
58	    public isTransversalAction(action: string | null | undefined): boolean {
59	        return this.categorize(action) === InteractionCategory.TRANSVERSAL;
60	    }
61	}
