1	import { GameState, NPC, SovereignAvatar } from '../../core/models.js';
2	import { SovereignAvatarEntity } from '../../core/SovereignAvatar.js';
3	import { GameplaySovereigntyLimb } from '../spatial/GameplaySovereigntyLimb.js';
4	import { TeleportGrounding } from '../spatial/TeleportGrounding.js';
5	import { ServerLogicRegistry, LogicalSignature } from '../../engines/gameplay/ServerLogicRegistry.js';
6	import { SovereignVocabularyLimb, InteractionCategory } from './SovereignVocabularyLimb.js';
7	import { VarbitSovereigntyLimb } from '../spatial/VarbitSovereigntyLimb.js';
8	import { ExtrasOracle } from './ExtrasOracle.js';
9	import { ClueLogicLimb } from './ClueLogicLimb.js';
10	import { WorldForensicsLimb } from '../spatial/WorldForensicsLimb.js';
11	import { createLogger } from '../../utils/logger.js';
12	import { getInteractionResult, isTransversal } from '../../forensics/ObjectBinaryStore.js';
13	
14	const logger = createLogger('InteractionGateway');
15	
16	export class InteractionGateway {
17	    private vocabLimb: SovereignVocabularyLimb;
18	    private extrasOracle: ExtrasOracle;
19	    private clueLimb: ClueLogicLimb;
20	
21	    constructor() {
22	        this.vocabLimb = new SovereignVocabularyLimb();
23	        this.extrasOracle = ExtrasOracle.getInstance();
24	        this.clueLimb = ClueLogicLimb.getInstance();
25	    }
26	
27	    /**
28	     * computeContextHash - Generates a fingerprint of the current state proximity.
29	     * Prevents interactions from firing if the world shifted significantly.
30	     */
31	    private computeContextHash(source: any, target: any, state: GameState): string {
32	        return `${source.x}_${source.y}_${target.x}_${target.y}_${state.tickNumber}`;
33	    }
34	
35	    public isAdjacent(sourceX: number, sourceY: number, targetX: number, targetY: number): boolean {
36	        return Math.abs(sourceX - targetX) <= 1 && Math.abs(sourceY - targetY) <= 1;
37	    }
38	
39	    public async evaluateInteraction(source: SovereignAvatar | NPC, action: string, targetId: string, state: GameState, activeModule: any): Promise<string[]> {
40	        const events: string[] = [];
41	        
42	        // 0. DETERMINISTIC STATE GUARD
43	        // Cooldown: 1 tick minimum between actions (600ms)
44	        if (source.lastActionTick && (state.tickNumber ?? 0) <= source.lastActionTick) {
45	            return [];
46	        }
47	
48	        if (source.interactionState === 'EXECUTING' || source.interactionState === 'COOLDOWN') {
49	            return [];
50	        }
51	
52	        // 1. Resolve Target
53	        const isItem = targetId.startsWith('item_');
54	        const isObject = targetId.startsWith('obj_');
55	        const isUI = targetId.startsWith('ui_') || targetId.includes(':');
56	        
57	        let target: any = null;
58	        let numericId = 0;
59	
60	        if (isUI && (action.toUpperCase() === 'SEARCH' || action.toUpperCase() === 'TYPESTRING')) {
61	            return this.evaluateSearchIntent(source, targetId, action, state);
62	        }
63	
64	        if (isItem) {
65	            // Expected format: item_<x>_<y>_<id>
66	            const parts = targetId.split('_');
67	            if (parts.length >= 4) {
68	                const ix = parseInt(parts[1], 10);
69	                const iy = parseInt(parts[2], 10);
70	                numericId = parseInt(parts[3], 10);
71	                
72	                // Locate item on the ground
73	                const key = `${ix}_${iy}`;
74	                const itemsOnTile = state.groundItems?.get(key) || [];
75	                const foundItem = itemsOnTile.find(i => i.id === numericId);
76	                
77	                if (foundItem) {
78	                    target = { ...foundItem, x: ix, y: iy, type: 'item' };
79	                }
80	            }
81	        } else {
82	            numericId = parseInt(targetId.replace('npc_', '').replace('obj_', ''), 10);
83	            target = state.npcMap.get(numericId) || state.objectMap.get(numericId);
84	        }
85	
86	        if (!target) return [];
87	
88	        // 1b. AUTHORITATIVE MORPHISM RESOLUTION (Phase 13)
89	        let activeId = numericId;
90	        if (isObject) {
91	            const varbitLimb = VarbitSovereigntyLimb.getInstance();
92	            const forensics = WorldForensicsLimb.getInstance();
93	            const def = await forensics.getObjectDefinition(numericId);
94	            activeId = varbitLimb.resolveCurrentObjectIdFromDef(def, state);
95	            if (activeId !== numericId) {
96	                const manifestedDef = await forensics.getObjectDefinition(activeId);
97	                target = { ...target, id: activeId, name: manifestedDef.name, actions: manifestedDef.actions };
98	                logger.info({ original: numericId, manifested: activeId }, '[InteractionGateway] Target morphed via Varbit/Varp.');
99	            }
100	        }
101	
102	        const sourceX = source.coord.x;
103	        const sourceY = source.coord.y;
104	        
105	        // 2. ADJACENCY LOCK
106	        if (!this.isAdjacent(sourceX, sourceY, target.x, target.y)) {
107	            source.interactionState = 'MOVING';
108	            return [];
109	        }
110	
111	        // 3. CONTEXT HASH VALIDATION (Intent Guard)
112	        const currentHash = this.computeContextHash(source, target, state);
113	        if (source.intent && source.intent.contextHash !== currentHash) {
114	             // If the intent is from a previous state/tick, re-verify or drop
115	             if ((state.tickNumber ?? 0) - (source.intent.tickStarted || 0) > 5) { // 3 second timeout
116	                 source.intent = undefined;
117	                 source.interactionState = 'IDLE';
118	                 return [`[InteractionGateway] Intent for ${target.name} expired or desynced.`];
119	             }
120	        }
121	
122	        // 4. TRANSITION TO EXECUTING
123	        source.interactionState = 'EXECUTING';
124	        source.lastActionTick = state.tickNumber ?? 0;
125	
126	        if (isItem) {
127	            if (action.toUpperCase() === 'PICKUP' || action.toUpperCase() === 'TAKE') {
128	                const key = `${target.x}_${target.y}`;
129	                const itemsOnTile = state.groundItems?.get(key) || [];
130	                const idx = itemsOnTile.findIndex((i: any) => i.id === target.id);
131	                if (idx > -1) {
132	                    const pickedUp = itemsOnTile.splice(idx, 1)[0];
133	                    if (itemsOnTile.length === 0) {
134	                        state.groundItems!.delete(key);
135	                    }
136	                    
137	                    if ('inventory' in source && (source as any).inventory && 'addItem' in source) {
138	                        const added = (source as any).addItem(pickedUp);
139	                        if (added) {
140	                            events.push(`[System] You picked up: ${pickedUp.itemName || 'Item ' + pickedUp.id}`);
141	                        } else {
142	                            // Inventory full, put it back
143	                            itemsOnTile.splice(idx, 0, pickedUp);
144	                            state.groundItems!.set(key, itemsOnTile);
145	                            events.push(`[System] Your inventory is too full to pick that up.`);
146	                        }
147	                    }
148	                }
149	            }
150	            source.interactionState = 'COOLDOWN';
151	            return events;
152	        }
153	
154	        // 3. MORPHISM INTEGRITY CHECK
155	        const manifestedDef = await WorldForensicsLimb.getInstance().getObjectDefinition(activeId);
156	        logger.info({ targetId, activeId, actions: manifestedDef.actions }, 'Authoritative Morphism Integrity Check');
157	        
158	        if (manifestedDef.actions && !manifestedDef.actions.includes(action)) {
159	            logger.warn({ action, targetId, manifestedId: activeId }, 'Interaction Gateway - Manifested action set mismatch. Rejecting.');
160	            return ['ACTION_STATE_GATED_REJECT'];
161	        }
162	
163	        // 5. CACHE ACTION VERIFICATION
164	        if (target.actions || (target.entity && target.entity.actions)) {
165	            const validActions: string[] = target.actions || target.entity.actions;
166	            const normalizedTargetAction = validActions.map(a => this.vocabLimb.normalizeHandle(a));
167	            const requested = this.vocabLimb.normalizeHandle(action);
168	            
169	            if (!normalizedTargetAction.includes(requested)) {
170	                source.interactionState = 'COOLDOWN';
