1	import { HandshakeOpcode, HandshakeResponse, type HandshakePacket, type HandshakeTranscript, type LoginBlock } from '../../core/HandshakeModels.js';
2	import { latestBuildNumber } from '../../core/CacheConstants.js';
3	import { createLogger } from "../../utils/logger.js";
4	import * as crypto from 'crypto';
5	
6	const logger = createLogger('HandshakeLimb');
7	
8	/**
9	 * HandshakeLimb - Protocol 947 Ingress Coordinator
10	 * Handles the authoritative "Dark Substrate" handshake for creating our own server bridge.
11	 */
12	export class HandshakeLimb {
13	    private static instance: HandshakeLimb;
14	    private transcript: HandshakeTranscript;
15	    private publicKey: string | null = null;
16	
17	    private constructor() {
18	        this.transcript = {
19	            sessionId: crypto.randomUUID(),
20	            protocolVersion: latestBuildNumber,
21	            phases: []
22	        };
23	    }
24	
25	    public static getInstance(): HandshakeLimb {
26	        if (!HandshakeLimb.instance) {
27	            HandshakeLimb.instance = new HandshakeLimb();
28	        }
29	        return HandshakeLimb.instance;
30	    }
31	
32	    /**
33	     * setKeys - Injects the RSA keys for the clean-room simulation.
34	     */
35	    public setKeys(publicKey: string): void {
36	        this.publicKey = publicKey;
37	        logger.debug("RSA Keys injected into Handshake Limb.");
38	    }
39	
40	    /**
41	     * generateJS5Hello - Creates the Opcode 15 Handshake packet.
42	     */
43	    public generateJS5Hello(): Buffer {
44	        const buffer = Buffer.alloc(5);
45	        buffer.writeUInt8(HandshakeOpcode.UPDATE_SERVICE, 0);
46	        buffer.writeUInt32BE(latestBuildNumber, 1);
47	
48	        this.logPhase('CLIENT_TO_SERVER', 'JS5_HELLO', buffer, { revision: latestBuildNumber });
49	        return buffer;
50	    }
51	
52	    /**
53	     * generateLoginHello - Phase 1 of Opcode 14.
54	     */
55	    public generateLoginHello(): Buffer {
56	        const buffer = Buffer.alloc(5);
57	        buffer.writeUInt8(HandshakeOpcode.LOGIN_SERVICE, 0);
58	        buffer.writeUInt32BE(latestBuildNumber, 1);
59	
60	        this.logPhase('CLIENT_TO_SERVER', 'LOGIN_HELLO', buffer, { revision: latestBuildNumber });
61	        return buffer;
62	    }
63	
64	    /**
65	     * generateLoginBlock - Phase 2 of Opcode 14 (The RSA Payload).
66	     */
67	    public generateLoginBlock(block: LoginBlock): Buffer {
68	        if (!this.publicKey) throw new Error("RSA Public Key must be injected before login.");
69	
70	        // 1. Construct raw payload
71	        // [magic(1), seeds(16), uid(length + 1), revision(2), username(str), ...]
72	        const payload = Buffer.alloc(256); // Start large
73	        let offset = 0;
74	        payload.writeUInt8(block.magic, offset++);
75	        
76	        for (const seed of block.isaacSeeds) {
77	            payload.writeUInt32BE(seed, offset);
78	            offset += 4;
79	        }
80	
81	        payload.write(block.uid, offset);
82	        offset += block.uid.length;
83	        payload.writeUInt8(0, offset++); // Null terminator for UID string
84	
85	        payload.writeUInt16BE(block.revision, offset);
86	        offset += 2;
87	
88	        payload.write(block.username, offset);
89	        offset += block.username.length;
90	        payload.writeUInt8(0, offset++);
91	
92	        const finalRaw = payload.slice(0, offset);
93	
94	        // 2. Encrypt via RSA
95	        const encrypted = crypto.publicEncrypt({
96	            key: this.publicKey,
97	            padding: crypto.constants.RSA_PKCS1_PADDING
98	        }, finalRaw);
99	
100	        this.logPhase('CLIENT_TO_SERVER', 'LOGIN_BLOCK_RSA', encrypted, { 
101	            rawSize: finalRaw.length,
102	            encryptedSize: encrypted.length 
103	        });
104	
105	        return encrypted;
106	    }
107	
108	    /**
109	     * processJS5Response - Validates the server's success byte.
110	     */
111	    public processJS5Response(data: Buffer): boolean {
112	        const response = data.readUInt8(0);
113	        this.logPhase('SERVER_TO_CLIENT', 'JS5_RESPONSE', data, { response });
114	
115	        if (response === HandshakeResponse.SUCCESS) {
116	            logger.info({ revision: latestBuildNumber }, "Handshake Successful: Revision 947 Established.");
117	            return true;
118	        }
119	
120	        logger.error({ response }, "Handshake Failed: Revision Mismatch or Server Full.");
121	        return false;
122	    }
123	
124	    /**
125	     * getTranscript - Returns the detailed forensic log.
126	     */
127	    public getTranscript(): HandshakeTranscript {
128	        return this.transcript;
129	    }
130	
131	    private logPhase(direction: 'CLIENT_TO_SERVER' | 'SERVER_TO_CLIENT', label: string, bytes: Buffer, semantic?: any): void {
132	        this.transcript.phases.push({
133	            timestamp: Date.now(),
134	            label,
135	            direction,
136	            bytes: bytes.toString('hex'),
137	            semantic
138	        });
139	    }
140	}
