60	   */
61	  private debounceSyncTrigger(): void {
62	    if (this.syncDebounceTimeout) {
63	      clearTimeout(this.syncDebounceTimeout);
64	    }
65	
66	    this.syncDebounceTimeout = setTimeout(() => {
67	      this.syncCorpus().catch(err => {
68	        logger.error({ err: err.message }, 'Failed to auto-sync corpus to Cloudflare R2.');
69	      });
70	    }, 5000); // Wait 5 seconds after the last change
