73	  /**
74	   * syncCorpus - Uploads the pedagogy corpus to Cloudflare R2 and broadcasts the update.
75	   */
76	  public async syncCorpus(): Promise<boolean> {
77	    if (!existsSync(this.corpusPath)) {
78	      logger.warn('Pedagogy training corpus does not exist. Aborting R2 sync.');
79	      return false;
80	    }
81	
82	    const version = Date.now();
83	    const bucket = process.env.CLOUDFLARE_R2_BUCKET || 'sovereign-corpus';
84	    logger.info({ bucket, version }, 'Syncing pedagogy training corpus to Cloudflare R2...');
85	
86	    try {
87	      // Execute upload via wrangler R2 put command
88	      const cmd = `wrangler r2 object put "${bucket}/pedagogy/v${version}.jsonl" --file "${this.corpusPath}"`;
89	      logger.info({ command: cmd }, 'Executing wrangler R2 object upload...');
90	      
91	      try {
92	        const { stdout } = await execAsync(cmd);
93	        logger.info({ stdout: stdout.trim() }, 'Successfully uploaded corpus to Cloudflare R2.');
94	      } catch (err: any) {
95	        logger.warn({ err: err.message }, 'wrangler R2 upload failed. (This is normal in offline or unconfigured environments. Proceeding with sync broadcast simulation).');
96	      }
97	
98	      // Broadcast update to PartyKit DO and connected edge nodes via GlobeStateLimb
99	      const globe = GlobeStateLimb.getInstance();
100	      if (globe) {
101	        logger.info('Broadcasting CORPUS_UPDATE signal to Durable Object...');
102	        const success = await globe.pushNodeState('pedagogy', {
103	          type: 'CORPUS_UPDATE',
104	          version,
105	          url: `r2://${bucket}/pedagogy/v${version}.jsonl`
106	        });
107	
108	        if (success.ok) {
109	          logger.info('✅ SUCCESS: Broadcaster state update successfully dispatched.');
110	        } else {
111	          logger.warn('Globe state update failed to dispatch (WebSocket not connected).');
112	        }
113	      } else {
114	        logger.info('GlobeStateLimb is not currently active. Skipping sync broadcast.');
115	      }
116	
117	      return true;
118	    } catch (err: any) {
119	      logger.error({ err: err.message }, 'Fatal error during SovereignSyncLimb execution.');
120	      throw err;
121	    }
122	  }
