8	/**
9	 * PedagogyForensicsLimb â€” The Instructional Substrate Auditor.
10	 * 
11	 * Manages the forensic links between pedagogical JSON instructions 
12	 * and the raw RS3 Cache substrate.
13	 */
14	export class PedagogyForensicsLimb {
15	    private static instance: PedagogyForensicsLimb;
16	    private readonly substratePath: string;
17	    private fileRegistry: Set<string> = new Set();
18	    private lookupMap: Map<string, string> = new Map(); // O(1) Lookup substrate
19	
20	    private constructor(path: string = 'D:/sovereign/memory/pedagogy') {
21	        this.substratePath = path;
22	        this.initializeRegistry();
23	    }
24	
25	    public static getInstance(): PedagogyForensicsLimb {
26	        if (!this.instance) {
27	            this.instance = new PedagogyForensicsLimb();
28	        }
29	        return this.instance;
30	    }
31	
32	    /**
33	     * initializeRegistry - Scans the pedagogy directory for all instruction files.
34	     */
35	    private initializeRegistry() {
36	        try {
37	            if (existsSync(this.substratePath)) {
38	                const files = readdirSync(this.substratePath, { recursive: true }) as string[];
39	                files.forEach(f => {
40	                    if (f.endsWith('.json')) {
41	                        const normalized = f.replace(/\\/g, '/');
42	                        this.fileRegistry.add(normalized);
43	                        
44	                        // Populate lookup map for O(1) resolution
45	                        const fileName = normalized.split('/').pop()?.toLowerCase().replace('.json', '');
46	                        if (fileName) this.lookupMap.set(fileName, normalized);
47	                    }
48	                });
49	                console.log(`[PEDAGOGY] Registry initialized with ${this.fileRegistry.size} nodes.`);
50	                logger.info({ count: this.fileRegistry.size, path: this.substratePath }, 'Pedagogical File Registry initialized (O(1) mapping active).');
51	
52	
53	            }
54	        } catch (err) {
55	            logger.warn('Pedagogy substrate unavailable. Clinical tracing will be limited.');
56	        }
57	    }
58	
59	    /**
60	     * resolvePedigree â€” Finds the specific instruction file for an entity or logic block.
61	     * Searches case-insensitively across normalized registry paths.
62	     */
63	    public resolvePedigree(identifier: string): string | null {
64	        const target = identifier.toLowerCase();
65	        
66	        // 1. O(1) Map Lookup (Optimal Path)
67	        const mapped = this.lookupMap.get(target);
68	        if (mapped) return mapped;
69	
70	        // 2. Fragment match fallback (O(F) - Rare)
71	        for (const file of this.fileRegistry) {
72	            const fileName = file.split('/').pop()?.toLowerCase();
73	            if (fileName?.includes(target)) return file;
74	        }
75	
76	        // 3. Systemic Logic Fallbacks
77	        if (target.includes('quest')) return 'logic/quest_manifest.json';
78	        if (target.includes('skill')) return 'logic/skill_manifest.json';
79	        if (target.includes('necro')) return 'logic/necromancy_logic.json';
80	
81	        return null;
82	    }
83	
84	
85	    /**
86	     * buildProvenance â€” Constructs a multi-phase provenance chain.
87	     */
88	    public buildProvenance(entityId: string, substrateProv: Provenance): Provenance {
89	        const pedigree = this.resolvePedigree(entityId);
90	        
91	        if (!pedigree) return substrateProv;
92	
93	        return {
94	            source: 'PEDAGOGY',
95	            recordId: pedigree,
96	            timestamp: Date.now(),
97	            path: join(this.substratePath, pedigree),
98	            ancestry: [substrateProv] // Link back to the raw global truth
99	        };
100	    }
101	
102	    public healthCheck(): { online: boolean; details: string } {
103	        return {
104	            online: this.fileRegistry.size > 0,
105	            details: `Pedagogy Forensics active. ${this.fileRegistry.size} instruction nodes indexed.`
106	        };
107	    }
108	}
