236	// COMBAT STATE MACHINE — Production-grade port from HTML prototype
237	// ─────────────────────────────────────────────────────────────────────────────
238	
239	export interface CombatTickState {
240	  tick: number;                  // Global tick counter
241	  adrenaline: number;            // 0-1000 internal (0-100% display)
242	  cooldowns: Map<string, number>; // abilityId → ticks remaining
243	  globalCooldown: number;        // GCD remaining ticks
244	  stunState: boolean;            // True if stunned
245	  channelState: {                // Active channel info
246	    abilityId: string | null;
247	    ticksRemaining: number;
248	    ticksTotal: number;
249	  };
250	  lastAutoAttackTick: number;    // For auto-attack timing
251	  combatStyle: 'MELEE' | 'RANGED' | 'MAGIC';
252	  activeBar: ActionBarState | null;
253	}
254	
255	export class CombatTickEngine {
256	
257	  private state: CombatTickState;
258	  private listeners: Set<(state: CombatTickState) => void> = new Set();
259	  private intervalId: ReturnType<typeof setInterval> | null = null;
260	  private readonly TICK_MS = 600; // RS3 standard tick
261	
262	  constructor(initialStyle: 'MELEE' | 'RANGED' | 'MAGIC' = 'MELEE') {
263	    this.state = {
264	      tick: 0,
265	      adrenaline: 0,
266	      cooldowns: new Map(),
267	      globalCooldown: 0,
268	      stunState: false,
269	      channelState: { abilityId: null, ticksRemaining: 0, ticksTotal: 0 },
270	      lastAutoAttackTick: 0,
271	      combatStyle: initialStyle,
272	      activeBar: null
273	    };
274	
275	    // Initialize all cooldowns to 0
276	    for (const id of Object.keys(ABILITY_LIBRARY)) {
277	      this.state.cooldowns.set(id, 0);
278	    }
279	  }
280	
281	// removed misaligned import
282	
283	// ... (existing class structure)
284	
285	  private isTicking: boolean = false;
286	
287	  start(): void {
288	    if (this.isTicking) return;
289	    this.isTicking = true;
290	    CanonicalClock.getInstance().registerPulse({
291	      domain: 'INFERENCE', // Aligned with reflex loop
292	      callback: (tick: number) => this.tick(),
293	      priority: 2, // after Adrenaline/CNS
294	      name: 'SovereignAvatarActionBarVolition'
295	    });
296	  }
297	
298	  stop(): void {
299	    this.isTicking = false;
300	  }
301	
302	
303	  private tick(): void {
304	    this.state.tick++;
305	
306	    if (!this.state.stunState) {
307	      this.state.adrenaline = Math.min(1000, this.state.adrenaline + 80);
308	    }
309	
310	    for (const [id, cd] of this.state.cooldowns) {
311	      if (cd > 0) this.state.cooldowns.set(id, cd - 1);
312	    }
313	
314	    if (this.state.globalCooldown > 0) this.state.globalCooldown--;
315	
316	    if (this.state.channelState.abilityId && this.state.channelState.ticksRemaining > 0) {
317	      this.state.channelState.ticksRemaining--;
318	      if (this.state.channelState.ticksRemaining <= 0) {
319	        this.state.channelState.abilityId = null;
320	      }
321	    }
322	
323	    if (this.state.tick - this.state.lastAutoAttackTick >= 3 && !this.state.channelState.abilityId) {
324	      this.executeAutoAttack();
325	    }
326	
327	    this.notifyListeners();
328	  }
329	
330	  private executeAutoAttack(): void {
331	    this.state.lastAutoAttackTick = this.state.tick;
332	    const damage = Math.floor(Math.random() * 20) + 5;
333	    this.emitEvent({ type: 'AUTO_ATTACK', damage, adrenalineDelta: 0 });
334	  }
335	
336	  useAbility(abilityId: string): boolean {
337	    const ability = ABILITY_LIBRARY[abilityId];
338	    if (!ability) return false;
339	
340	    if (this.state.stunState) {
341	      this.emitEvent({ type: 'BLOCKED', reason: 'STUNNED', abilityId });
342	      return false;
343	    }
344	
345	    if (this.state.channelState.abilityId) {
346	      this.emitEvent({ type: 'BLOCKED', reason: 'CHANNELING', abilityId });
347	      return false;
348	    }
349	
350	    const cd = this.state.cooldowns.get(abilityId) || 0;
351	    if (cd > 0) {
352	      this.emitEvent({ type: 'BLOCKED', reason: 'COOLDOWN', abilityId, cooldownRemaining: cd });
353	      return false;
354	    }
355	
356	    if (this.state.adrenaline < ability.adrenReq) {
357	      this.emitEvent({ type: 'BLOCKED', reason: 'ADRENALINE', abilityId, 
358	        current: this.state.adrenaline, required: ability.adrenReq });
359	      return false;
360	    }
361	
362	    if (this.state.globalCooldown > 0) {
363	      this.emitEvent({ type: 'BLOCKED', reason: 'GCD', abilityId, gcdRemaining: this.state.globalCooldown });
364	      return false;
365	    }
366	
367	    const prevAdren = this.state.adrenaline;
368	    this.state.adrenaline = Math.max(0, Math.min(1000, this.state.adrenaline + ability.adrenGain));
369	    this.state.cooldowns.set(abilityId, ability.cooldown);
370	    this.state.globalCooldown = 1;
371	
372	    let damage = 0;
373	    if (ability.damageRange[0] > 0) {
374	      damage = Math.floor(Math.random() * (ability.damageRange[1] - ability.damageRange[0] + 1)) 
375	               + ability.damageRange[0];
376	    }
377	
378	    if (ability.isChannelled) {
379	      this.state.channelState = {
380	        abilityId,
381	        ticksRemaining: ability.channelTicks,
382	        ticksTotal: ability.channelTicks
383	      };
384	    }
385	
386	    this.emitEvent({
387	      type: 'ABILITY',
388	      abilityId,
389	      tier: ability.tier,
390	      damage,
391	      adrenalineBefore: prevAdren,
392	      adrenalineAfter: this.state.adrenaline,
393	      isChannelled: ability.isChannelled,
394	      channelTicks: ability.channelTicks
395	    });
396	
397	    this.notifyListeners();
398	    return true;
399	  }
400	
401	  setActionBar(barState: ActionBarState): void {
402	    this.state.activeBar = barState;
403	    this.notifyListeners();
404	  }
405	
406	  applyStun(durationTicks: number): void {
407	    this.state.stunState = true;
408	    setTimeout(() => { this.state.stunState = false; }, durationTicks * this.TICK_MS);
409	    this.emitEvent({ type: 'STUN', duration: durationTicks });
410	  }
411	
412	  private eventListeners: Set<(event: CombatEvent) => void> = new Set();
413	
414	  onEvent(listener: (event: CombatEvent) => void): () => void {
415	    this.eventListeners.add(listener);
416	    return () => this.eventListeners.delete(listener);
417	  }
418	
419	  private emitEvent(event: CombatEvent): void {
420	    for (const listener of this.eventListeners) {
421	      try { listener(event); } catch (e) { console.error('Combat event error:', e); }
422	    }
423	  }
424	
425	  getState(): Readonly<CombatTickState> { return this.state; }
426	
427	  onStateChange(listener: (state: CombatTickState) => void): () => void {
428	    this.listeners.add(listener);
429	    return () => this.listeners.delete(listener);
430	  }
431	
432	  private notifyListeners(): void {
433	    for (const listener of this.listeners) {
434	      try { listener(this.state); } catch (e) { console.error('State listener error:', e); }
435	    }
436	  }
437	}
438	
439	export type CombatEvent =
440	  | { type: 'ABILITY'; abilityId: string; tier: string; damage: number; adrenalineBefore: number; adrenalineAfter: number; isChannelled: boolean; channelTicks: number }
441	  | { type: 'AUTO_ATTACK'; damage: number; adrenalineDelta: number }
442	  | { type: 'BLOCKED'; reason: 'STUNNED' | 'COOLDOWN' | 'ADRENALINE' | 'GCD' | 'CHANNELING'; abilityId: string; cooldownRemaining?: number; current?: number; required?: number; gcdRemaining?: number }
443	  | { type: 'STUN'; duration: number };
