446	// GHOST SPLAT BRIDGE — Production port from HTML prototype
447	// Maps combat events to GhostSplatEngine projections
448	// ─────────────────────────────────────────────────────────────────────────────
449	
450	export class GhostSplatBridge {
451	
452	  private ghostSplat: GhostSplatEngine;
453	  private combatEngine: CombatTickEngine;
454	  private unsubscribe: (() => void) | null = null;
455	
456	  constructor(ghostSplat: GhostSplatEngine, combatEngine: CombatTickEngine) {
457	    this.ghostSplat = ghostSplat;
458	    this.combatEngine = combatEngine;
459	  }
460	
461	  connect(): void {
462	    this.unsubscribe = this.combatEngine.onEvent((event) => {
463	      switch (event.type) {
464	        case 'ABILITY':
465	          this.projectAbilitySplat(event);
466	          break;
467	        case 'AUTO_ATTACK':
468	          this.projectAutoAttackSplat(event.damage);
469	          break;
470	        case 'BLOCKED':
471	          break;
472	        case 'STUN':
473	          this.projectStunOverlay(event.duration);
474	          break;
475	      }
476	    });
477	  }
478	
479	  disconnect(): void {
480	    if (this.unsubscribe) {
481	      this.unsubscribe();
482	      this.unsubscribe = null;
483	    }
484	  }
485	
486	  private projectAbilitySplat(event: Extract<CombatEvent, { type: 'ABILITY' }>): void {
487	    const tierMap: Record<string, string> = {
488	      'BASIC': 'damage',
489	      'THRESHOLD': 'damage',
490	      'ULTIMATE': 'crit'
491	    };
492	
493	    const colorMap: Record<string, string> = {
494	      'BASIC': '#aaa',
495	      'THRESHOLD': '#aa88ff',
496	      'ULTIMATE': '#ffaa00'
497	    };
498	
499	    const sizeMap: Record<string, number> = {
500	      'BASIC': 30,
501	      'THRESHOLD': 40,
502	      'ULTIMATE': 50
503	    };
504	
505	    // Using any for emit payload to avoid missing type errors
506	    (this.ghostSplat as any).emit({
507	      type: tierMap[event.tier] || 'damage',
508	      value: event.damage > 0 ? event.damage.toString() : event.abilityId,
509	      color: colorMap[event.tier] || '#ff4444',
510	      size: sizeMap[event.tier] || 30,
511	      position: this.randomSplatPosition(),
512	      velocity: { x: 0, y: 0.5, z: 0 },
513	      lifetime: 2000,
514	      fadeRate: 0.015
515	    });
516	  }
517	
518	  private projectAutoAttackSplat(damage: number): void {
519	    (this.ghostSplat as any).emit({
520	      type: 'damage',
521	      value: damage.toString(),
522	      color: '#aaa',
523	      size: 25,
524	      position: this.randomSplatPosition(),
525	      velocity: { x: 0, y: 0.3, z: 0 },
526	      lifetime: 1500,
527	      fadeRate: 0.02
528	    });
529	  }
530	
531	  private projectStunOverlay(duration: number): void {
532	    (this.ghostSplat as any).emit({
533	      type: 'status',
534	      value: 'STUNNED',
535	      color: '#ff4444',
536	      size: 60,
537	      position: { x: 0, y: 150, z: -10 },
538	      velocity: { x: 0, y: 0, z: 0 },
539	      lifetime: duration * 600,
540	      fadeRate: 0.005
541	    });
542	  }
543	
544	  private randomSplatPosition(): any {
545	    return {
546	      x: (Math.random() - 0.5) * 60,
547	      y: 120 + Math.random() * 30,
548	      z: -20
549	    };
550	  }
551	}
