574	    if (!el) throw new Error(`Action bar container #${containerId} not found`);
575	    this.container = el;
576	    this.initDOM();
577	  }
578	
579	  private initDOM(): void {
580	    this.container.innerHTML = '';
581	    this.slotElements = [];
582	
583	    for (let i = 0; i < 14; i++) {
584	      const slot = document.createElement('div');
585	      slot.className = 'ability-slot empty-slot';
586	      slot.id = `slot-${i}`;
587	      this.container.appendChild(slot);
588	      this.slotElements.push(slot);
589	    }
590	
591	    this.adrenalineFill = document.getElementById('adrenaline-fill');
592	    this.adrenalineText = document.getElementById('adrenaline-text');
593	    this.tickCounter = document.getElementById('tick-counter');
594	    this.logContainer = document.getElementById('log-entries');
595	  }
596	
597	  render(barState: ActionBarState, combatState: CombatTickState): void {
598	    if (this.adrenalineFill && this.adrenalineText) {
599	      const pct = combatState.adrenaline / 10;
600	      this.adrenalineFill.style.height = pct + '%';
601	      this.adrenalineText.textContent = Math.floor(pct) + '%';
602	      this.adrenalineText.style.color = pct >= 100 ? '#ffaa00' : pct >= 50 ? '#aa88ff' : '#fff';
603	    }
604	
605	    if (this.tickCounter) {
606	      this.tickCounter.textContent = combatState.tick.toString();
607	    }
608	
609	    for (let i = 0; i < 14; i++) {
610	      const slot = barState.slots[i];
611	      const el = this.slotElements[i];
612	      if (!el) continue;
613	
614	      if (!slot || !slot.abilityId) {
615	        el.className = 'ability-slot empty-slot';
616	        el.style.backgroundImage = 'none';
617	        el.innerHTML = '';
618	        continue;
619	      }
620	
621	      const ability = ABILITY_LIBRARY[slot.abilityId];
622	      if (!ability) continue;
623	
624	      const cd = combatState.cooldowns.get(slot.abilityId.toString()) || 0;
625	      const canUse = combatState.adrenaline >= ability.adrenReq && cd === 0 && !combatState.stunState;
626	
627	      const classes = ['ability-slot', `tier-${ability.tier}`];
628	      if (cd > 0) classes.push('cooldown');
629	      else if (canUse) classes.push('ready');
630	      else classes.push('unavailable');
631	
632	      el.className = classes.join(' ');
633	
634	      const iconName = ability.name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
635	      el.style.backgroundImage = `url('icons/${iconName}.png')`;
636	
637	      const tierBadge = ability.tier === 'ULTIMATE' ? 'U' : ability.tier === 'THRESHOLD' ? 'T' : 'B';
638	      let html = `
639	        <div style="position: absolute; inset: 0; background: linear-gradient(to bottom, transparent 40%, rgba(0,0,0,0.85)); border-radius: 3px; z-index: 1;"></div>
640	        <span class="ability-name">${ability.name}</span>
641	        <span class="tier-badge">${tierBadge}</span>
642	      `;
643	
644	      if (cd > 0) {
645	        html += `<div class="cooldown-overlay">${cd}</div>`;
646	      }
647	
648	      el.innerHTML = html;
649	    }
650	  }
651	
652	  log(message: string, cssClass: string = ''): void {
653	    if (!this.logContainer) return;
654	    const div = document.createElement('div');
655	    div.className = 'log-entry ' + cssClass;
656	    div.textContent = '> ' + message;
657	    this.logContainer.insertBefore(div, this.logContainer.firstChild);
658	    while (this.logContainer.children.length > 12) {
659	      const last = this.logContainer.lastChild;
660	      if (last) this.logContainer.removeChild(last);
661	    }
662	  }
663	
664	  destroy(): void {
665	    this.container.innerHTML = '';
666	    this.slotElements = [];
667	  }
668	}
