678	  private adrenalineSM: AdrenalineStateMachine;
679	  private rotationEngine: CombatRotationEngine;
680	  private abilityLimb: AbilityDiscoveryLimb;
681	  private ghostSplat: GhostSplatEngine;
682	  private ghostBridge: GhostSplatBridge;
683	  private renderer: ActionBarRenderer | null = null;
684	
685	  private combatUnsub: (() => void) | null = null;
686	  private tickUnsub: (() => void) | null = null;
687	
688	  constructor(deps: {
689	    agent: PlayerAgent;
690	    adrenalineSM: AdrenalineStateMachine;
691	    rotationEngine: CombatRotationEngine;
692	    abilityLimb: AbilityDiscoveryLimb;
693	    ghostSplat: GhostSplatEngine;
694	  }) {
695	    this.agent = deps.agent;
696	    this.adrenalineSM = deps.adrenalineSM;
697	    this.rotationEngine = deps.rotationEngine;
698	    this.abilityLimb = deps.abilityLimb;
699	    this.ghostSplat = deps.ghostSplat;
700	
701	    const style = this.detectCombatStyle();
702	    this.combatEngine = new CombatTickEngine(style);
703	    this.ghostBridge = new GhostSplatBridge(this.ghostSplat, this.combatEngine);
704	  }
705	
706	  initialize(): void {
707	    this.ghostBridge.connect();
708	
709	    this.combatUnsub = this.combatEngine.onEvent((event) => {
710	      if (this.renderer && 'type' in event) {
711	        switch (event.type) {
712	          case 'ABILITY':
713	            const tierCls = event.tier.toLowerCase();
714	            this.renderer.log(
715	              `${event.abilityId} → ${event.damage > 0 ? event.damage + ' dmg' : 'ACTIVE'}`,
716	              tierCls === 'basic' ? 'basic' : tierCls
717	            );
718	            break;
719	          case 'BLOCKED':
720	            this.renderer.log(
721	              `${event.abilityId}: ${event.reason} (${event.cooldownRemaining || event.current || event.gcdRemaining || ''})`,
722	              'system'
723	            );
724	            break;
725	          case 'STUN':
726	            this.renderer.log(`STUNNED for ${event.duration} ticks`, 'system');
727	            break;
728	        }
729	      }
730	    });
731	
732	    this.tickUnsub = this.combatEngine.onStateChange((state) => {
733	      if (this.renderer && state.activeBar) {
734	        this.renderer.render(state.activeBar, state);
735	      }
736	    });
737	
738	    this.combatEngine.start();
739	  }
740	
741	  bindRenderer(renderer: ActionBarRenderer): void {
742	    this.renderer = renderer;
743	  }
744	
745	  loadActionBar(rawInterface1841: any): void {
746	    const barState = I1841Integration.Translator.translate(rawInterface1841);
747	    this.combatEngine.setActionBar(barState);
748	  }
749	
750	  executeAbility(abilityId: string): boolean {
751	    return this.combatEngine.useAbility(abilityId);
752	  }
753	
754	  executeRotationSlot(slotIndex: number): boolean {
755	    const bar = this.combatEngine.getState().activeBar;
756	    if (!bar || !bar.slots[slotIndex]) return false;
757	
758	    const abilityId = bar.slots[slotIndex].abilityId;
759	    if (!abilityId) return false;
760	
761	    return this.combatEngine.useAbility(abilityId.toString());
762	  }
763	
764	  applyStun(durationTicks: number): void {
765	    this.combatEngine.applyStun(durationTicks);
766	  }
767	
768	  destroy(): void {
769	    this.combatEngine.stop();
770	    this.ghostBridge.disconnect();
771	    if (this.combatUnsub) this.combatUnsub();
772	    if (this.tickUnsub) this.tickUnsub();
773	    if (this.renderer) this.renderer.destroy();
774	  }
775	
776	  private detectCombatStyle(): 'MELEE' | 'RANGED' | 'MAGIC' {
777	    // Fallback to MELEE if getSkillVector fails or is missing
778	    try {
779	      const skills = (this.agent as any).getSkillVector();
780	      if (skills) {
781	        const melee = skills[0] + skills[1];
782	        const ranged = skills[3] * 2;
783	        const magic = skills[5] * 2;
784	
785	        if (ranged > melee && ranged > magic) return 'RANGED';
786	        if (magic > melee && magic > ranged) return 'MAGIC';
787	      }
788	    } catch (e) {
789	      // Ignore and use default
790	    }
791	    return 'MELEE';
792	  }
793	
794	  getCombatState(): Readonly<CombatTickState> {
795	    return this.combatEngine.getState();
796	  }
797	
798	  getAdrenaline(): number {
799	    return this.combatEngine.getState().adrenaline;
800	  }
801	
802	  isChanneling(): boolean {
803	    return this.combatEngine.getState().channelState.abilityId !== null;
804	  }
805	}
