126	// CACHE-TO-AGENT TRANSLATOR
127	// Maps raw interface JSON to typed ActionBarState for PlayerAgent consumption
128	// ─────────────────────────────────────────────────────────────────────────────
129	
130	export class I1841CacheTranslator {
131	
132	  /**
133	   * Translate raw cache-extracted interface JSON into runtime ActionBarState.
134	   * Called by CacheForensicsLimb after opcode decoding.
135	   */
136	  static translate(rawInterface: any): ActionBarState {
137	    const components: I1841ComponentConfig[] = rawInterface.components;
138	
139	    // Find root and validate structure
140	    const root = components.find(c => c.componentId === I1841.ROOT);
141	    if (!root) throw new Error('I1841: Root component 2 not found');
142	
143	    // Extract script operands for initialization
144	    const initScript = root.scripts.load;
145	    const barIndex = this.extractBarIndex(initScript);
146	
147	    // Build slot map from SLOT_CONTAINER (11) and its children
148	    const slotContainer = components.find(c => c.componentId === I1841.SLOT_CONTAINER);
149	    const slots = this.buildSlots(components, slotContainer);
150	
151	    return {
152	      interfaceId: 1841,
153	      activeBarIndex: barIndex,
154	      isLocked: false,
155	      adrenaline: 0,
156	      adrenalineThreshold: null,
157	      slots,
158	      revolutionActive: false,
159	      revolutionSlots: [],
160	      stunState: false,
161	      globalCooldown: 0
162	    };
163	  }
164	
165	  private static extractBarIndex(script: number[]): number {
166	    if (script.length >= 2 && script[0] === I1841.SCRIPT_INIT) {
167	      return 1;
168	    }
169	    return 1;
170	  }
171	
172	  private static buildSlots(
173	    components: I1841ComponentConfig[], 
174	    container: I1841ComponentConfig | undefined
175	  ): ActionBarSlot[] {
176	    const slots: ActionBarSlot[] = [];
177	    if (!container) return slots;
178	
179	    const staticSlots = [I1841.SLOT_CHILD_0, I1841.SLOT_CHILD_1];
180	
181	    for (let i = 0; i < 14; i++) {
182	      const compId = i < staticSlots.length 
183	        ? staticSlots[i] 
184	        : container.children[i] || (100 + i);
185	
186	      slots.push({
187	        componentId: compId,
188	        abilityId: null,
189	        abilityName: null,
190	        cooldownRemaining: 0,
191	        cooldownTotal: 0,
192	        adrenalineCost: 0,
193	        adrenalineThreshold: 0,
194	        isAvailable: false,
195	        isDragTarget: false,
196	        spriteId: null,
197	        varpBinding: 767 + i
198	      });
199	    }
200	
201	    return slots;
202	  }
203	}
